import axios from "axios";

const API_URL =
  process.env.REACT_APP_API_URL || "https://www.space-flow.dev/api";

const api = axios.create({
  baseURL: API_URL,
  headers: {
    "Content-Type": "application/json",
  },
});

// Единый интерцептор для токена
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("token");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error),
);

// Единый интерцептор для обработки ответов и ошибок
api.interceptors.response.use(
  (response) => {
    // В 2026 году бэкенд на SQLAlchemy 2.0 отдает чистые числа,
    // но на случай старых данных оставляем конвертацию Decimal
    const convertDecimals = (obj) => {
      if (Array.isArray(obj)) return obj.map(convertDecimals);
      if (obj && typeof obj === "object") {
        if (obj.__Decimal__ !== undefined) return parseFloat(obj.str) || 0;
        const result = {};
        for (const key in obj) result[key] = convertDecimals(obj[key]);
        return result;
      }
      return obj;
    };
    if (response.data) response.data = convertDecimals(response.data);
    return response;
  },
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem("token");
      localStorage.removeItem("user");
      if (!window.location.pathname.includes("/login")) {
        window.location.href = "/login";
      }
    }
    return Promise.reject(error);
  },
);

export const authAPI = {
  register: (userData) => api.post("/auth/register", userData),
  login: (credentials) => api.post("/auth/login", credentials),
  logout: () => api.post("/auth/logout"),
};

export const userAPI = {
  me: () => api.get("/users/me"),
  update: (userData) => api.put("/users/me", userData),
  setTelegramId: (telegramId) => api.post("/users/set-telegram-id", telegramId),
};

export const receiptsAPI = {
  getReceipts: (skip = 0, limit = 100) =>
    api.get("/receipts", { params: { skip, limit } }),
  uploadReceipt: (file) => {
    const formData = new FormData();
    formData.append("file", file);
    return api.post("/receipts/upload-json", formData, {
      headers: { "Content-Type": "multipart/form-data" },
    });
  },
  createReceipt: (receiptData) => api.post("/receipts/", receiptData),
};

export const analyticsAPI = {
  // Общая статистика за всё время
  getTotalSums: () => api.get("/analytics/total-sums"),

  // Месячная динамика
  getMonthlyDynamics: (year = new Date().getFullYear()) =>
    api.get("/analytics/monthly-dynamics", { params: { year } }),

  // Топ товаров
  getTopProducts: (months = 3, limit = 10) =>
    api.get("/analytics/top-products", { params: { months, limit } }),

  // Получить статистику по магазинам (уже есть в stores, но оставим если нужно)
  getStoreStats: (skip = 0, limit = 100) =>
    api.get("/analytics/store-stats", { params: { skip, limit } }),

  // Новый эндпоинт: получить расходы по категориям (если есть)
  getCategoryStats: (year = new Date().getFullYear()) =>
    api
      .get("/analytics/category-stats", { params: { year } })
      .catch(() => ({ data: [] })),

  // Новый эндпоинт: средний чек по месяцам
  getAverageReceipt: (year = new Date().getFullYear()) =>
    api
      .get("/analytics/average-receipt", { params: { year } })
      .catch(() => ({ data: [] })),
};

export const storesAPI = {
  getStores: ({ page, page_size, sort_by, descending }) =>
    api.get("/stores/", {
      params: { page, page_size, sort_by, descending },
    }),

  getStoreStats: () => api.get("/stores/stats"),

  createStore: (storeData) => api.post("/stores/", storeData),

  // Важно: на бэкенде нужно будет добавить эндпоинт для этого PUT
  updateStore: (storeId, storeData) => api.put(`/stores/${storeId}`, storeData),

  deleteStore: (storeId) => api.delete(`/stores/${storeId}`),
};

export default api;
